function kc(conc, coeff){ var num=1, den=1;
  for(var i=0;i<conc.length;i++){ var e=Math.abs(coeff[i]); var c=Math.max(conc[i],0); var term=Math.pow(c,e);
    if(coeff[i]>0) num*=term; else den*=term; }
  return num/den; }
var EXPORTS={kc:kc};

if (typeof module !== 'undefined' && module.exports) { module.exports = EXPORTS; }
if (typeof window !== 'undefined') { window.EquilibriumForgePure = EXPORTS; }
